      ui(()->{LinearLayout sample=DesignUi.column(activity);ReleaseNotesRenderer.append(sample,ReleaseNotes.parse("## 可读标题\n- 正常列表","",true).user);CharSequence value=((TextView)sample.getChildAt(0)).getText();if(!(value instanceof Spanned)||((Spanned)value).getSpans(0,value.length(),BulletSpan.class).length!=1||((Spanned)value).getSpans(0,value.length(),StyleSpan.class).length!=1||value.toString().contains("##")||value.toString().contains("- 正常"))throw new AssertionError("Missing native heading/list spans");});check("Native headings and bullets use spans",true);
      ui(()->{activity.historyVisible=20;activity.historyRevision=-1;activity.refreshHistory(version);count[0]=versions(activity.historyBody);});check("More history displays twenty entries from cache",count[0]==20);
      long before=fixture.status().getLong("revision");ui(()->{StrictMode.ThreadPolicy previous=StrictMode.getThreadPolicy();StrictMode.setThreadPolicy(new StrictMode.ThreadPolicy.Builder().detectDiskReads().detectDiskWrites().detectNetwork().penaltyDeath().build());try{for(int i=0;i<50;i++)prepared.status();}finally{StrictMode.setThreadPolicy(previous);}});check("Repeated prepared history status has no main-thread I/O",fixture.status().getLong("revision")==before);
      fixture.direct=url->{throw new IOException("Controlled history failure before HTTP");};fixture.opener=(url,proxy)->{throw new IOException("Controlled history failure before HTTP");};fixture.load(activity.historyClient,20,true);long deadline=SystemClock.elapsedRealtime()+10000;while(fixture.status().getBoolean("loading")&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(20);check("History failure keeps cached rows independently",!fixture.status().getBoolean("loading")&&!fixture.status().getString("error","").isEmpty()&&fixture.visible(100,"").size()==30);
